// A tiny OpenAI-compatible server for trying the real OpenAI code path WITHOUT an API key or network.
// It answers /v1/chat/completions with schema-valid output generated by the offline engine.
//   node scripts/fake-openai.mjs [port]      then run the API with:  AI_ENGINE=openai OPENAI_API_KEY=x OPENAI_BASE_URL=http://localhost:4011/v1
import http from 'node:http';
import { MockEngine } from '../src/ai/mock.js';
import { WORKFLOWS } from '../src/schemas.js';

const engine = new MockEngine(), port = Number(process.argv[2] || 4011);
const SAMPLE = { resume: { resumeText: 'x'.repeat(300) }, skill_gap: { targetRole: 'Data Analyst', currentSkills: ['sql'] }, roadmap: { currentBackground: 'Some background text', targetRole: 'Data Analyst' }, interview: { role: 'Backend Developer' }, answer_feedback: { question: 'Tell me about a time you led.', answer: 'x'.repeat(80) } };

http.createServer(async (req, res) => {
  let raw = ''; for await (const c of req) raw += c;
  try {
    const body = JSON.parse(raw), kind = body.response_format?.json_schema?.name, user = body.messages?.at(-1)?.content || '';
    // Pull the interesting inputs back out of the prompt so the fake answer is at least on-topic.
    const pick = (re, d) => (re.exec(user)?.[1] ?? d);
    const base = WORKFLOWS[kind].input.parse(SAMPLE[kind]);
    if (kind === 'skill_gap') base.targetRole = pick(/"([^"]+)" role/, base.targetRole);
    if (kind === 'resume') base.resumeText = pick(/<user_data name="resume">\n([\s\S]*?)\n<\/user_data>/, base.resumeText);
    const out = await engine.run(kind, base);
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ id: 'fake', object: 'chat.completion', model: body.model, choices: [{ index: 0, finish_reason: 'stop', message: { role: 'assistant', content: JSON.stringify(out) } }] }));
  } catch (e) { res.writeHead(400, { 'content-type': 'application/json' }); res.end(JSON.stringify({ error: { message: String(e.message) } })); }
}).listen(port, () => console.log(`fake OpenAI listening on http://localhost:${port}/v1`));
